82					t.Errorf("error must name file, record 1 and field %q: %v", tc.field, err)
83				}
84	
85				// Health, baseline health and history all refuse with no result.
86				if _, err := store.Health("n1", testBase, "1.0", 0); err == nil || !IsCorrupt(err) {
87					t.Errorf("health must refuse corrupt data, got %v", err)
88				}
