90					t.Errorf("health with baseline must refuse corrupt data, got %v", err)
91				}
92				if _, err := store.History("n1"); err == nil || !IsCorrupt(err) {
93					t.Errorf("history must refuse corrupt data, got %v", err)
94				}
95			})
96		}
