141	
142		const obj = `"node":"n1","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.0","height":100,"missed":0`
143		// Literal JSON Unicode escapes denoting the same keys as "missed"
144		// (i=U+0069), "height" (e=U+0065) and "node" (o=U+006F).
145		escMissed := "\"m\\u0069ssed\""
146		escHeight := "\"h\\u0065ight\""
147		escNode := "\"n\\u006fde\""
148		cases := []struct {
149			name        string
