151			field       string
152		}{
153			{"duplicate missed same value", `[{` + obj + `,"missed":0}]`, "missed"},
154			{"duplicate missed diff value", `[{` + obj + `,"missed":1}]`, "missed"},
155			{"duplicate height same value", `[{` + obj + `,"height":100}]`, "height"},
156			{"duplicate node", `[{"node":"n1",` + obj + `}]`, "node"},
157			{"duplicate seq", `[{` + obj + `,"seq":2}]`, "seq"},
158			{"duplicate collected_at", `[{` + obj + `,"collected_at":"2026-10-01T11:59:00Z"}]`, "collected_at"},
159			{"duplicate version", `[{` + obj + `,"version":"2.0"}]`, "version"},
160			// A Unicode-escaped spelling of the same key counts as a duplicate.
161			{"duplicate missed via unicode escape", `[{` + obj + `,` + escMissed + `:1}]`, "missed"},
162			{"duplicate height via unicode escape", `[{` + obj + `,` + escHeight + `:101}]`, "height"},
163			{"duplicate node via unicode escape", `[{` + escNode + `:"n2",` + obj + `}]`, "node"},
164		}
