278		// node. The whole batch must be refused before anything is saved.
279		batch := []Heartbeat{
280			hb("bad", 2, receive.Add(-time.Second), "1.0", 102, 0),
281			hb("good", 2, receive.Add(-time.Second), "1.0", 101, 0),
282			hb("fresh", 1, receive.Add(-time.Second), "1.0", 1, 0),
283		}
