309			t.Fatalf("good node must stay queryable: %v", err)
310		}
311		if r.Seq != 1 {
312			t.Errorf("good node seq=%d, want 1 (rejected batch changed nothing)", r.Seq)
313		}
314		if _, _, err := store.Submit([]Heartbeat{hb("good", 3, receive.Add(-time.Second), "1.0", 103, 0)}, receive); err != nil {
315			t.Errorf("submitting to a different, healthy node must work: %v", err)
316		}
317	}
