// nodeIDFromPath recovers the node id a store file belongs to from its
// location: short ids are stored as <nodes>/hex(nodeID).json and long ids as
// nested directories of nodeNameChunk hex characters ending in the remaining
// hex segment plus ".json" (see nodePathFor). The owner is the exact string
// those hex bytes decode to — ids with Chinese characters, emoji or spaces
// decode back unchanged and are never normalised.
//
// The location must additionally be exactly the canonical location for that
// owner: nodePathFor over the first non-chunk ancestor must produce this same
// path. A foreign node's well-formed file copied to another node's long-id
// path therefore fails here (its decoded owner's canonical path is elsewhere),
// as do stray subdirectories, mis-sized segments and upper-cased hex names,
// regardless of format marker or checksum.
func nodeIDFromPath(path string) (string, error) {
	path = filepath.Clean(path)
	base := filepath.Base(path)
	if !strings.HasSuffix(base, ".json") {
		return "", fmt.Errorf("file name %q is not a per-node heartbeat file", base)
	}
	tail := strings.TrimSuffix(base, ".json")
	if !isHex(tail) {
		return "", fmt.Errorf("file name %q does not encode a node id", base)
	}

	// Gather the fixed-size hex directory components, innermost first.
	var chunks []string
	dir := filepath.Dir(path)
	for {
		part := filepath.Base(dir)
		if len(part) != nodeNameChunk || !isHex(part) {
			break
		}
		chunks = append(chunks, part)
		dir = filepath.Dir(dir)
	}

	// chunks were gathered innermost-first; rebuild the encoding by
	// prepending each one to the tail, starting with the innermost.
	encoded := tail
	for _, chunk := range chunks {
		encoded = chunk + encoded
	}
	raw, err := hex.DecodeString(encoded)
	if err != nil {
		return "", fmt.Errorf("file name %q does not encode a node id: %w", base, err)
	}
	owner := string(raw)
	if owner == "" {
		return "", fmt.Errorf("file name %q encodes an empty node id", base)
	}
	if canonical := nodePathFor(dir, owner); canonical != path {
		return "", fmt.Errorf("file %q is not the canonical storage location for node %q", path, owner)
	}
	return owner, nil
}

