		t.Fatal(err)
	}
	if files != len(ids) {
		t.Errorf("files on disk = %d, want %d", files, len(ids))
	}
	if sharded != len(ids) {
		t.Errorf("sharded files = %d, want all %d long ids sharded", sharded, len(ids))
	}
}

